import { StructuredTool, BaseToolkit } from '@langchain/core/tools';
import { z } from 'zod';
import { CallbackManagerForToolRun } from '@langchain/core/callbacks/manager';
import { RunnableConfig } from '@langchain/core/runnables';

type Context = {
    merchant_id?: string;
    sandbox?: boolean;
    access_token?: string;
    request_id?: string;
    tenant_context?: any;
    debug?: boolean;
    [key: string]: any;
};
type Configuration = {
    actions: {
        [product: string]: {
            [action: string]: boolean;
        };
    };
    context?: Context;
};

declare class PayPalClient {
    private _sdkClient;
    private _clientId;
    private _clientSecret;
    private _isSandbox;
    private _accessToken;
    private _baseUrl;
    private _context;
    constructor({ clientId, clientSecret, context }: {
        clientId: string;
        clientSecret: string;
        context: Context;
    });
    constructor({ context, accessToken }: {
        context: Context;
        accessToken?: string;
    });
    private createSDKClient;
    getAccessToken(): Promise<string>;
    getBaseUrl(): string;
    getHeaders(): Promise<Record<string, string>>;
    private generateUserAgent;
}

declare class PayPalAPI {
    paypalClient: PayPalClient;
    context: Context;
    baseUrl: string;
    accessToken?: string;
    constructor(paypalClientOrAccessToken: PayPalClient | string, context?: Context);
    run(method: string, arg: any): Promise<string>;
    private executeMethod;
}

declare class PayPalTool extends StructuredTool {
    PayPalAPI: PayPalAPI;
    method: string;
    name: string;
    description: string;
    schema: z.ZodObject<any, any, any, any>;
    constructor(PayPalAPI: PayPalAPI, method: string, name: string, description: string, schema: z.ZodObject<any, any, any, any, {
        [x: string]: any;
    }>);
    _call(arg: z.output<typeof this.schema>, _runManager?: CallbackManagerForToolRun, _parentConfig?: RunnableConfig): Promise<any>;
}

/**
 * PayPal Agent LangChain Toolkit in TypeScript
 */

declare class PayPalAgentToolkit implements BaseToolkit {
    readonly client: PayPalClient;
    private _paypal;
    tools: PayPalTool[];
    constructor({ clientId, clientSecret, configuration, }: {
        clientId: string;
        clientSecret: string;
        configuration: Configuration;
    });
    getTools(): PayPalTool[];
}

type Tool = {
    method: string;
    name: string;
    description: string;
    parameters: z.ZodObject<any, any, any, any>;
    actions: {
        [key: string]: {
            [action: string]: boolean;
        };
    };
};
declare const ALL_TOOLS_ENABLED: {
    [key: string]: {
        [key: string]: boolean;
    };
};

export { ALL_TOOLS_ENABLED, PayPalAPI, PayPalAgentToolkit, type Tool };
